def transform(grid):
    h, w = len(grid), len(grid[0])

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def dominant_line(values):
        counts = {}
        for value in values:
            counts[value] = counts.get(value, 0) + 1
        color = max(counts, key=counts.get)
        return color if counts[color] / len(values) >= 0.65 and color != background else None

    row_lines = [(r, dominant_line(grid[r])) for r in range(h)]
    col_lines = [(c, dominant_line([grid[r][c] for r in range(h)])) for c in range(w)]

    rows = [(r, color) for r, color in row_lines if color is not None]
    cols = [(c, color) for c, color in col_lines if color is not None]

    line_counts = {}
    for _, color in rows + cols:
        line_counts[color] = line_counts.get(color, 0) + 1
    line_color = max(line_counts, key=line_counts.get)

    rows = [r for r, color in rows if color == line_color]
    cols = [c for c, color in cols if color == line_color]

    marked = [(i, j) for i, r in enumerate(rows) for j, c in enumerate(cols)
              if grid[r][c] != line_color]
    if not marked:
        return [[background]]

    r0 = min(i for i, _ in marked)
    r1 = max(i for i, _ in marked)
    c0 = min(j for _, j in marked)
    c1 = max(j for _, j in marked)

    out = [[background for _ in range(c1 - c0)] for _ in range(r1 - r0)]
    for i in range(r0, r1):
        for j in range(c0, c1):
            corners = [
                grid[rows[i]][cols[j]],
                grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]],
                grid[rows[i + 1]][cols[j + 1]],
            ]
            if corners[0] != line_color and all(x == corners[0] for x in corners):
                out[i - r0][j - c0] = corners[0]
    return out
